class Solution
{
public:
    int numWays(int n, int k)
    {
        if (n == 0)
        {
            return 0;
        }
        long long same = 0, diff = k;
        for (int i = 2; i <= n;++i)
        {
            long long ns = diff, nd = (same + diff)*(k - 1);
            same = ns;
            diff = nd;
        }
        return(int) (same + diff);
    }
};
